44	    private String city;
45	
46	    @Column(name = "telephone")
47	    @NotEmpty
48	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form")
49	    private String telephone;
50	
51	    @Column(name = "email")
52	    private String email;
53	
54	    @Column(name = "postcode")
55	    private String postcode;
56	
57	    public String getPostcode() {
58	        return this.postcode;
59	    }
60	
61	    public void setPostcode(String postcode) {
62	        this.postcode = postcode;
63	    }
64	
65	    @Column(name = "registration_date")
66	    private LocalDate registrationDate;
67	
68	    @Column(name = "birth_date")
69	    private LocalDate birthDate;
70	
71	    public LocalDate getBirthDate() {
72	        return this.birthDate;
73	    }
74	
75	    public void setBirthDate(LocalDate birthDate) {
76	        this.birthDate = birthDate;
77	    }
78	
79	    @Column(name = "customer_code")
80	    private String customerCode;
81	
82	    @Column(name = "namesake_count")
83	    private Integer namesakeCount;
84	
85	    @Column(name = "household_size")
86	    private Integer householdSize;
87	
88	    public String getCustomerCode() {
89	        return this.customerCode;
90	    }
91	
92	    public void setCustomerCode(String customerCode) {
93	        this.customerCode = customerCode;
94	    }
95	
96	    public Integer getNamesakeCount() {
97	        return this.namesakeCount;
98	    }
99	
100	    public void setNamesakeCount(Integer namesakeCount) {
101	        this.namesakeCount = namesakeCount;
102	    }
103	
104	    public Integer getHouseholdSize() {
105	        return this.householdSize;
106	    }
107	
108	    public void setHouseholdSize(Integer householdSize) {
109	        this.householdSize = householdSize;
110	    }
111	
112	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
113	    private Set<Pet> pets;
114	
115	    public String getEmail() {
116	        return this.email;
117	    }
118	
119	    public void setEmail(String email) {
120	        this.email = email;
121	    }
122	
123	    public LocalDate getRegistrationDate() {
124	        return this.registrationDate;
125	    }
126	
