19	import java.nio.charset.StandardCharsets;
20	import java.security.MessageDigest;
21	import java.security.NoSuchAlgorithmException;
22	import java.util.Locale;
23	
24	import org.springframework.samples.petclinic.model.Owner;
25	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
26	
27	/**
28	 * Derives an owner's {@code identityKey}, the single value all duplicate detection is based on:
29	 * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}. Kept as a small
30	 * standalone unit so the request advice and the response mapper derive the key identically.
31	 */
32	public final class OwnerIdentityKey {
33	
34	    private OwnerIdentityKey() {
35	    }
36	
37	    static String of(OwnerFieldsDto owner) {
38	        return of(owner.getTelephone(), owner.getEmail(), owner.getLastName(), owner.getPostcode());
39	    }
40	
41	    public static String of(Owner owner) {
42	        return of(owner.getTelephone(), owner.getEmail(), owner.getLastName(), owner.getPostcode());
43	    }
44	
45	    static String of(String telephone, String email, String lastName, String postcode) {
46	        return telephone(telephone) + '|' + email(email) + '|' + householdId(lastName, postcode);
47	    }
48	
49	    static String telephone(String telephone) {
50	        return OwnerTelephoneNormalizationAdvice.toE164(telephone);
51	    }
52	
53	    static String email(String email) {
54	        return (email == null || email.isBlank()) ? "" : email.strip().toLowerCase(Locale.ROOT);
55	    }
56	
57	    /**
58	     * Stable household identifier: the first 12 hex characters of SHA-256 over
59	     * {@code normalizedLastName + '|' + postcode}, so owners with the same last name and postcode
60	     * share it automatically.
61	     */
62	    public static String householdId(String lastName, String postcode) {
63	        String normalized = lastName.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT)
64	            + '|' + (postcode == null ? "" : postcode.trim());
65	        return sha256Hex(normalized).substring(0, 12);
66	    }
67	
68	    private static String sha256Hex(String value) {
69	        try {
70	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
71	            StringBuilder sb = new StringBuilder(digest.length * 2);
72	            for (byte b : digest) {
73	                sb.append(String.format("%02x", b));
74	            }
75	            return sb.toString();
76	        }
77	        catch (NoSuchAlgorithmException e) {
78	            throw new IllegalStateException(e);
79	        }
80	    }
81	}
