25	/**
26	 * Records, on each newly-created owner just before it is saved, how many existing owners already
27	 * share its first and last name (compared case-insensitively). Kept as its own small aspect so this
28	 * rule stays a self-contained unit rather than growing the controller or service.
29	 */
30	@Aspect
31	@Component
32	public class OwnerNamesakeCountAdvice {
33	
34	    private final OwnerRepository ownerRepository;
35	
36	    public OwnerNamesakeCountAdvice(OwnerRepository ownerRepository) {
37	        this.ownerRepository = ownerRepository;
38	    }
39	
40	    @Before("execution(* org.springframework.samples.petclinic.service.ClinicService.saveOwner(..)) && args(owner)")
41	    public void assignNamesakeCount(Owner owner) {
42	        if (owner.isNew() && owner.getNamesakeCount() == null) {
43	            owner.setNamesakeCount((int) ownerRepository.findAll().stream()
44	                .filter(other -> sameName(owner.getFirstName(), other.getFirstName())
45	                    && sameName(owner.getLastName(), other.getLastName()))
46	                .count());
47	        }
48	    }
49	
50	    private static boolean sameName(String a, String b) {
51	        return a != null && a.equalsIgnoreCase(b);
52	    }
53	}
