18	
19	import java.nio.charset.StandardCharsets;
20	import java.security.MessageDigest;
21	import java.security.NoSuchAlgorithmException;
22	import java.util.Map;
23	
24	import org.aspectj.lang.annotation.Aspect;
25	import org.aspectj.lang.annotation.Before;
26	import org.springframework.samples.petclinic.model.Owner;
27	import org.springframework.stereotype.Component;
28	
29	/**
30	 * Assigns a customerCode '<REGION>-<HASH8>' to each newly-created owner just before it is saved:
31	 * REGION is the region code derived from the postcode (its 4-digit range, else "UNKNOWN") and HASH8
32	 * is the first 8 upper-case hex characters of SHA-256 over (normalizedTelephone + lastName). Kept as
33	 * its own small aspect so this rule stays a self-contained unit rather than growing the controller
34	 * or service.
35	 */
36	@Aspect
37	@Component
38	public class OwnerCustomerCodeAdvice {
39	
40	    /** Postcode band (4-digit / 100) -> region code. */
41	    private static final Map<Integer, String> REGION = Map.of(20, "NSW", 30, "VIC", 40, "QLD");
42	
43	    @Before("execution(* org.springframework.samples.petclinic.service.ClinicService.saveOwner(..)) && args(owner)")
44	    public void assignCustomerCode(Owner owner) {
45	        if (owner.isNew() && owner.getCustomerCode() == null) {
46	            String pc = owner.getPostcode();
47	            int band = pc != null && pc.matches("[0-9]{4}") ? Integer.parseInt(pc) / 100 : -1;
48	            try {
49	                byte[] d = MessageDigest.getInstance("SHA-256")
50	                    .digest((owner.getTelephone() + owner.getLastName()).getBytes(StandardCharsets.UTF_8));
51	                String hash8 = String.format("%02X%02X%02X%02X", d[0], d[1], d[2], d[3]);
52	                owner.setCustomerCode(REGION.getOrDefault(band, "UNKNOWN") + "-" + hash8);
53	            }
54	            catch (NoSuchAlgorithmException e) {
55	                throw new IllegalStateException(e);
56	            }
57	        }
58	    }
59	}
