36	/**
37	 * Rejects an owner whose email domain is on a disposable-domain blocklist, answering with
38	 * a 400. The email is optional: absent or blank emails, and emails on other domains, are
39	 * accepted. Kept as its own advice so this rule stays a small, self-contained unit.
40	 */
41	@ControllerAdvice
42	@Order(Ordered.HIGHEST_PRECEDENCE)
43	public class OwnerDisposableEmailAdvice extends RequestBodyAdviceAdapter {
44	
45	    private static final Set<String> BLOCKED_DOMAINS =
46	        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
47	
48	    @Override
49	    public boolean supports(MethodParameter methodParameter, Type targetType,
50	                            Class<? extends HttpMessageConverter<?>> converterType) {
51	        return OwnerFieldsDto.class.equals(targetType);
52	    }
53	
54	    @Override
55	    public Object afterBodyRead(Object body, HttpInputMessage inputMessage, MethodParameter parameter,
56	                                Type targetType, Class<? extends HttpMessageConverter<?>> converterType) {
57	        OwnerFieldsDto owner = (OwnerFieldsDto) body;
58	        if (isDisposable(owner.getEmail())) {
59	            throw new DisposableEmailException();
60	        }
61	        return body;
62	    }
63	
64	    private boolean isDisposable(String email) {
65	        if (email == null) {
66	            return false;
67	        }
68	        int at = email.lastIndexOf('@');
69	        if (at < 0) {
70	            return false;
71	        }
72	        String domain = email.substring(at + 1).strip().toLowerCase(Locale.ROOT);
73	        return BLOCKED_DOMAINS.contains(domain);
74	    }
75	
76	    @ExceptionHandler(DisposableEmailException.class)
77	    @ResponseBody
78	    public ResponseEntity<String> handleDisposableEmail(DisposableEmailException e) {
79	        return ResponseEntity.status(HttpStatus.BAD_REQUEST).body(e.getMessage());
80	    }
81	
82	    /** Signals an email whose domain is on the disposable-domain blocklist. */
83	    static class DisposableEmailException extends RuntimeException {
84	
85	        DisposableEmailException() {
86	            super("email domain is not allowed");
87	        }
88	    }
89	}
