35	/**
36	 * JPA implementation of the {@link OwnerRepository} interface.
37	 *
38	 * @author Mike Keith
39	 * @author Rod Johnson
40	 * @author Sam Brannen
41	 * @author Michael Isvy
42	 * @author Vitaliy Fedoriv
43	 */
44	@Repository
45	@Profile("jpa")
46	public class JpaOwnerRepositoryImpl implements OwnerRepository {
47	
48	    @PersistenceContext
49	    private EntityManager em;
50	
51	
52	    /**
53	     * Important: in the current version of this method, we load Owners with all their Pets and Visits while
54	     * we do not need Visits at all and we only need one property from the Pet objects (the 'name' property).
55	     * There are some ways to improve it such as:
56	     * - creating a Ligtweight class (example here: https://community.jboss.org/wiki/LightweightClass)
57	     * - Turning on lazy-loading and using open session in view pattern
58	     */
59	    @SuppressWarnings("unchecked")
60	    public Collection<Owner> findByLastName(String lastName) {
61	        // using 'join fetch' because a single query should load both owners and pets
62	        // using 'left join fetch' because it might happen that an owner does not have pets yet
63	        Query query = this.em.createQuery("SELECT DISTINCT owner FROM Owner owner left join fetch owner.pets WHERE owner.lastName LIKE :lastName");
64	        query.setParameter("lastName", lastName + "%");
65	        return query.getResultList();
66	    }
67	
68	    @Override
69	    @SuppressWarnings("unchecked")
70	    public Page<Owner> findByLastName(String lastName, Pageable pageable) throws DataAccessException {
71	        Query query = this.em.createQuery("SELECT owner FROM Owner owner WHERE owner.lastName LIKE :lastName ORDER BY owner.id");
72	        query.setParameter("lastName", lastName + "%");
