17	package org.springframework.samples.petclinic.rest.advice;
18	
19	import java.time.LocalDate;
20	import java.time.temporal.ChronoUnit;
21	
22	import org.springframework.samples.petclinic.model.Owner;
23	
24	/**
25	 * Derives an owner's {@code membershipPoints} and the {@code membershipLevel} mapped from
26	 * them. Points start at 0 and add 2 for a present email, 1 for a zero namesakeCount, 2 for
27	 * a household of 3 or more and 3 for tenure over 365 days from the registrationDate. The
28	 * level is 1 for 0-1 points, 2 for 2-3, 3 for 4-5 and 4 for 6 or more. Kept as a small
29	 * standalone unit so the response mapper can expose both values without growing.
30	 */
31	public final class OwnerMembershipLevel {
32	
33	    private OwnerMembershipLevel() {
34	    }
35	
36	    public static int points(Owner owner) {
37	        return (hasEmail(owner) ? 2 : 0)
38	            + (Integer.valueOf(0).equals(owner.getNamesakeCount()) ? 1 : 0)
39	            + (largeHousehold(owner) ? 2 : 0)
40	            + (tenuredOver365(owner) ? 3 : 0);
41	    }
42	
43	    public static int of(Owner owner) {
44	        int p = points(owner);
45	        return p <= 1 ? 1 : p <= 3 ? 2 : p <= 5 ? 3 : 4;
46	    }
47	
48	    private static boolean largeHousehold(Owner owner) {
49	        return owner.getHouseholdSize() != null && owner.getHouseholdSize() >= 3;
50	    }
51	
52	    private static boolean hasEmail(Owner owner) {
53	        return owner.getEmail() != null && !owner.getEmail().isBlank();
54	    }
55	
56	    private static boolean tenuredOver365(Owner owner) {
57	        LocalDate registered = owner.getRegistrationDate();
58	        return registered != null && ChronoUnit.DAYS.between(registered, LocalDate.now()) > 365;
59	    }
60	}
